/**
 * Interaction correlation — one authoritative voice interaction from two sources.
 *
 * Sources (both existing, both read-only here):
 *   esl : Dashboard `callState` — the queue call FreeSWITCH/mod_callcenter offered to THIS
 *         agent (agent-scoped socket events + /agent-desk/calls poll).
 *         { phase: 'ringing'|'talking', callUuid, ani, caller_name, queueName, startedAt }
 *   sip : browser phone CallInfo from the softphone engine (status !== 'ended' unless ending).
 *
 * There is NO shared identifier: the SIP session id is generated by sip.js and the
 * FreeSWITCH call_uuid is not sent to the browser. We never invent one. The two are LINKED
 * only when every condition below holds; otherwise both are kept and a warning is shown.
 *
 *   1. the ESL call is offered to this agent (agent-scoped event / poll)          — scope
 *   2. the browser phone is this agent's registered contact (signed in)            — device
 *   3. the SIP call is INBOUND (mod_callcenter calls the agent; agents never
 *      dial into their own queue call)                                            — direction
 *   4. both are live at the same time (engine allows one call at a time)          — timing
 *   5. caller numbers do not conflict: equal digits, one a suffix of the other
 *      (+971… vs 0…), or one side missing                                         — consistency
 *
 * A matching number alone is never enough: conditions 1–4 must also hold.
 */

export const LINK = {
  LINKED: 'linked',             // ESL + SIP describe the same call
  PHONE_ONLY: 'phone-only',     // direct (non-queue) call on the browser phone
  QUEUE_ONLY: 'queue-only',     // queue call, no browser call (yet / other device)
  UNLINKED: 'unlinked',         // both present but conditions failed — shown separately
};

export function digits(value) {
  // digits only, national trunk zeros dropped (0501… and +971 501… compare equal by suffix)
  return String(value ?? '').replace(/^sips?:/i, '').split('@')[0].replace(/\D/g, '').replace(/^0+/, '');
}

/** true when the two numbers can be the same caller (or one is unknown). */
export function numbersCompatible(a, b) {
  const x = digits(a);
  const y = digits(b);
  if (!x || !y) return true;
  if (x === y) return true;
  const [short, long] = x.length <= y.length ? [x, y] : [y, x];
  return short.length >= 6 && long.endsWith(short);
}

function sipStatus(call) {
  switch (call.status) {
    case 'ringing-in': return 'ringing';
    case 'dialing': return 'dialing';
    case 'ringing-out': return 'ringing-out';
    case 'connecting': return 'connecting';
    case 'active': return call.held ? 'held' : 'connected';
    case 'ended': return 'ended';
    default: return call.status;
  }
}

function sipNumber(identity) {
  if (!identity) return undefined;
  const m = String(identity).match(/sips?:([^@;>]+)/i);
  return m ? m[1] : String(identity);
}

/**
 * @param {object}  p
 * @param {object?} p.esl             Dashboard callState or null
 * @param {object?} p.sip             engine CallInfo or null
 * @param {boolean} p.phoneSignedIn   browser phone registered for this agent
 * @returns {{ interaction: object|null, link: string, warning: string|null, queueCall: object|null }}
 */
export function correlate({ esl, sip, phoneSignedIn }) {
  const liveEsl = esl && (esl.phase === 'ringing' || esl.phase === 'talking') ? esl : null;
  const liveSip = sip || null;

  if (!liveEsl && !liveSip) return { interaction: null, link: null, warning: null, queueCall: null };

  const fromEsl = liveEsl && {
    callUuid: liveEsl.callUuid,
    number: liveEsl.ani || undefined,
    name: liveEsl.caller_name || undefined,
    queue: liveEsl.queueName || undefined,
    startedAt: liveEsl.startedAt,
  };

  if (liveSip) {
    const base = {
      id: liveSip.id,
      channel: 'voice',
      direction: liveSip.direction,
      status: sipStatus(liveSip),
      muted: liveSip.muted,
      held: liveSip.held,
      answeredAt: liveSip.answeredAt,
      endReason: liveSip.endReason,
      number: sipNumber(liveSip.remoteIdentity),
      controllable: true,
      sources: { sip: liveSip, esl: liveEsl },
    };

    if (!liveEsl) {
      return { interaction: { ...base, kind: liveSip.direction === 'outbound' ? 'outbound' : 'direct' }, link: LINK.PHONE_ONLY, warning: null, queueCall: null };
    }

    const linkable = phoneSignedIn && liveSip.direction === 'inbound' && numbersCompatible(fromEsl.number, base.number);
    if (linkable) {
      return {
        interaction: {
          ...base,
          kind: 'queue',
          callUuid: fromEsl.callUuid,
          number: fromEsl.number || base.number,
          name: fromEsl.name,
          queue: fromEsl.queue,
        },
        link: LINK.LINKED,
        warning: null,
        queueCall: null,
      };
    }

    return {
      interaction: { ...base, kind: liveSip.direction === 'outbound' ? 'outbound' : 'direct' },
      link: LINK.UNLINKED,
      warning: 'A queue call and a browser-phone call are active at the same time and could not be confirmed as the same call. They are shown separately.',
      queueCall: fromEsl,
    };
  }

  // Queue call only (no browser call).
  const ringing = liveEsl.phase === 'ringing';
  return {
    interaction: {
      id: liveEsl.callUuid,
      channel: 'voice',
      kind: 'queue',
      direction: 'inbound',
      callUuid: fromEsl.callUuid,
      number: fromEsl.number,
      name: fromEsl.name,
      queue: fromEsl.queue,
      startedAt: fromEsl.startedAt,
      status: ringing ? 'offering' : 'connected-elsewhere',
      controllable: false,
      sources: { esl: liveEsl },
    },
    link: LINK.QUEUE_ONLY,
    warning: ringing
      ? (phoneSignedIn
        ? 'Queue call offered — waiting for it to ring in the browser phone.'
        : 'Queue call offered — it rings on your phone device (browser phone is not signed in).')
      : (phoneSignedIn
        ? 'FreeSWITCH reports this queue call as connected, but the browser phone has no active call. It may be answered on another device.'
        : 'Connected on your phone device. Call controls are available on that device only.'),
    queueCall: null,
  };
}
